def comparisons(items, target):
    count = 0
    for item in items:
        count += 1
        if item == target:
            break
    return count

assert comparisons([2, 4, 6], 9) == 3
assert comparisons([], 9) == 0

def reversed_copy(items):
    result = []
    for i in range(len(items) - 1, -1, -1):
        result.append(items[i])
    return result

assert reversed_copy([1, 2, 3]) == [3, 2, 1]

