def first_repeat(items):
    seen = set()
    for item in items:
        if item in seen:
            return item
        seen.add(item)
    return None

assert first_repeat(['a', 'b', 'a']) == 'a'
assert first_repeat([]) is None

def balanced(text):
    depth = 0
    for char in text:
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

assert balanced('(())')
assert not balanced(')(')

