def binary_search(values, target):
    low, high = 0, len(values) - 1
    while low <= high:
        mid = (low + high) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

assert binary_search([2, 5, 8, 12, 16], 12) == 3

def total(tree):
    return tree['minutes'] + sum(total(child) for child in tree['children'])

tree = {'minutes': 10, 'children': [{'minutes': 20, 'children': []}]}
assert total(tree) == 30

